-- Empty plan selection is valid, and still auditable.
savepoint empty_scope;
create temporary table empty_events as select count(*) as count from public.security_events where action='timplan_list_read' and customer_id='55005000-0000-4000-8000-000000000001' and assignment_id=(select id from planning_roles where name='principal');
delete from public.class_timplans where timplan_id in (select id from public.timplans where offering_id in ('55005000-0000-4000-8000-000000000040','55005000-0000-4000-8000-000000000043'));
delete from public.timplan_cells where timplan_id in (select id from public.timplans where offering_id in ('55005000-0000-4000-8000-000000000040','55005000-0000-4000-8000-000000000043'));
delete from public.timplans where offering_id in ('55005000-0000-4000-8000-000000000040','55005000-0000-4000-8000-000000000043');
select is((public.phase5_list_timplans(1)->>'count')::int,0,'empty scope returns zero count');
select is(jsonb_array_length(public.phase5_list_timplans(1)->'plans'),0,'empty scope returns no plans');
select is((select count(*) from public.security_events where action='timplan_list_read' and object_type='timplan_collection' and object_id is null and customer_id='55005000-0000-4000-8000-000000000001' and assignment_id=(select id from planning_roles where name='principal')),(select count+2 from empty_events),'every empty list records collection audit');
rollback to empty_scope;
