-- Multi-page scope shares a deterministic order and exact total.
insert into public.timplans(id,organizer_id,offering_id,version,basis,status,decided_on,unit_id)
select ('55005000-0000-4000-8000-'||lpad((200+n)::text,12,'0'))::uuid,'55005000-0000-4000-8000-000000000002','55005000-0000-4000-8000-000000000040',n+2,'Syntetisk grund','ersatt',public.app_today(),'55005000-0000-4000-8000-000000000030' from generate_series(1,55) n;
create temporary table pages as select public.phase5_list_timplans(1) as first,public.phase5_list_timplans(2) as second;
select is((select (first->>'count')::int from pages),58,'pagination count includes all scoped versions');
select is((select jsonb_array_length(first->'plans') from pages),50,'first page fixed at 50');
select is((select jsonb_array_length(second->'plans') from pages),8,'second page has remainder');
select ok((select not exists(select 1 from jsonb_array_elements(first->'plans') p join jsonb_array_elements(second->'plans') q on p->>'id'=q->>'id') from pages),'pages never duplicate IDs');
select is((select first->'plans'->0->>'version' from pages),'57','latest matching version sorts first');
select is(public.phase5_list_timplans(1),(select first from pages),'repeated page is stable while data unchanged');
-- Worker list gets only a temporary grant in this rolled-back test.
grant execute on function public.phase5_list_timplans(integer) to skolplattform_worker;
set local role skolplattform_worker;
select throws_ok($q$select public.phase5_list_timplans(1)$q$,'55000',null,'Worker list needs actual session');
reset role;
insert into public.app_sessions(id,token_hash,identity_id,membership_id,assignment_id,expires_at,absolute_expires_at)
values('55005000-0000-4000-8000-000000000080',decode(md5('55005000-0000-4000-8000-000000000080')||md5('55005000-0000-4000-8000-000000000080'),'hex'),'55005000-0000-4000-8000-000000000011','55005000-0000-4000-8000-000000000021',(select id from planning_roles where name='principal'),clock_timestamp()+interval '1 hour',clock_timestamp()+interval '8 hours');
select set_config('app.session_id','55005000-0000-4000-8000-000000000080',true);
set local role skolplattform_worker;
select lives_ok($q$select public.phase5_list_timplans(1)$q$,'Worker session-bound list succeeds');
reset role;
select ok(exists(select 1 from public.security_events where action='timplan_list_read' and source='db' and session_id='55005000-0000-4000-8000-000000000080' and actor_identity_id='55005000-0000-4000-8000-000000000011' and membership_id='55005000-0000-4000-8000-000000000021' and assignment_id=(select id from planning_roles where name='principal') and customer_id='55005000-0000-4000-8000-000000000001' and object_id is null and object_type='timplan_collection' and details='{}'),'list audit uses actual session tuple');
update public.app_sessions set revoked_at=clock_timestamp() where id='55005000-0000-4000-8000-000000000080';
set local role skolplattform_worker;
select throws_ok($q$select public.phase5_list_timplans(1)$q$,'55000',null,'revoked session blocks list');
reset role;
update public.app_sessions set revoked_at=null where id='55005000-0000-4000-8000-000000000080';
create function pg_temp.reject_selection_audit() returns trigger language plpgsql as $$begin
 if new.customer_id='55005000-0000-4000-8000-000000000001' and new.action='timplan_list_read' then raise exception 'Syntetiskt loggfel'; end if; return new;
end $$;
create trigger selection_audit_failure before insert on public.security_events for each row execute function pg_temp.reject_selection_audit();
select throws_ok($q$select public.phase5_list_timplans(1)$q$,'55000',null,'generic DB audit error fails closed for list');
drop trigger selection_audit_failure on public.security_events;
select is(has_function_privilege('anon','public.phase5_list_timplans(integer)','execute'),false,'anon list entry remains closed');
select is(has_function_privilege('authenticated','public.phase5_list_timplans(integer)','execute'),false,'authenticated list entry remains closed');
select is((select count(*) from pg_proc p where p.pronamespace='public'::regnamespace and p.proname like 'phase5_%' and has_function_privilege('skolplattform_worker',p.oid,'execute')),8::bigint,'exactly eight Worker entrypoints inside temporary grant; helpers closed');
select ok(not exists(select 1 from pg_proc p cross join lateral aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a where p.pronamespace='public'::regnamespace and p.proname like 'phase5_%' and a.grantee=0 and a.privilege_type='EXECUTE'),'PUBLIC has no phase5 execute');
select * from finish();
rollback;
